using Microsoft.EntityFrameworkCore;namespace QuanLyDatTour.Models;public class QLDatTourContext:DbContext{public QLDatTourContext(DbContextOptions<QLDatTourContext> o):base(o){}public DbSet<Tour> Tour=>Set<Tour>();public DbSet<KhachHang> KhachHang=>Set<KhachHang>();public DbSet<DatTour> DatTour=>Set<DatTour>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Tour>().HasKey(x=>x.MaTour);b.Entity<Tour>().Property(x=>x.GiaNgoaiTe).HasColumnType("decimal(18,2)");b.Entity<Tour>().Property(x=>x.NgoaiTe).HasColumnType("char(3)");b.Entity<KhachHang>().HasKey(x=>x.MaKH);b.Entity<DatTour>().HasKey(x=>x.MaDat);b.Entity<DatTour>().Property(x=>x.TyGia).HasColumnType("decimal(18,4)");b.Entity<DatTour>().Property(x=>x.TongTienVND).HasColumnType("decimal(18,0)");b.Entity<DatTour>().HasOne(x=>x.KhachHang).WithMany().HasForeignKey(x=>x.MaKH);b.Entity<DatTour>().HasOne(x=>x.Tour).WithMany().HasForeignKey(x=>x.MaTour);}}